CREATE DATABASE IF NOT EXISTS volvo_antifraud;
USE volvo_antifraud;

DROP TABLE IF EXISTS order_details;
DROP TABLE IF EXISTS service_orders;
DROP TABLE IF EXISTS volvo_cars;

CREATE TABLE volvo_cars (vin VARCHAR(17) PRIMARY KEY, model VARCHAR(20), sale_date DATE);
CREATE TABLE service_orders (order_id INT PRIMARY KEY, vin VARCHAR(17), visit_date DATE, close_date DATE, customer_complaint TEXT, diagnostic_result TEXT, repair_status TEXT, dealer_name VARCHAR(50), master_name VARCHAR(50), approver_signature VARCHAR(50));
CREATE TABLE order_details (record_id INT PRIMARY KEY, order_id INT, item_type VARCHAR(20), sku_or_operation VARCHAR(20), item_name VARCHAR(100), cost DECIMAL(10,2), labor_hours DECIMAL(4,2));

